function M.metadata(name)
  local cfg = require("sessions.config").cfg
  local path = cfg.root .. "/" .. name .. ".vim"
  return require("sessions.meta").read(path)
end

local function capture(node)
  if node[1] == "leaf" then
    local winid = node[2]
    return { "leaf", { width = api.nvim_win_get_width(winid), height = api.nvim_win_get_height(winid) } }
  end
  local kind, children = node[1], node[2]
  local out = {}
  for i, child in ipairs(children) do out[i] = capture(child) end
  return { kind, out }
end

function M.delete(session_path)
  os.remove(meta_path(session_path))
end

local function pat_escape(s)
  return (s:gsub("[%(%)%.%%%+%-%*%?%[%]%^%$]", "%%%1"))
end

local function repl_escape(s)
  return (s:gsub("%%", "%%%%"))
end
